import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const { parseHTML } = require(process.argv[2]);
const root = resolve("crates/gwt/web");
const { createUiStateStore } = await import(pathToFileURL(resolve(root,"ui-state-store.js")));
const { runTerminalActivationSequence } = await import(pathToFileURL(resolve(root,"terminal-viewport-reflow.js")));
const app = readFileSync(resolve(root,"app.js"),"utf8");
const extract = name => app.match(new RegExp(`      function ${name}\\([^]*?^      \\}`, "m"))?.[0];
const source = readFileSync(resolve("target/issue-5390-works-surface-fixture-before.mjs"),"utf8");
const definitions = source.slice(source.indexOf("const windows ="),source.indexOf('test("Works implements'));
const counts = { layouts:0, catalog:0, fits:0, geometry:0, frames:0 };
const fixture = new Function("parseHTML","createUiStateStore","moduleUrl","counts",
  definitions.replace("onLayout() {}", "onLayout() { counts.layouts++; }") + "; return fixture;")(
  parseHTML,createUiStateStore,pathToFileURL(resolve(root,"works-surface.js")),counts);
const f = await fixture();
f.windowCatalogModel.subscribe(s=>s.catalog,()=>{counts.catalog++;});
const drain = () => { let limit=0; while(f.frames.size){ if(++limit>20) throw Error("frame cycle did not settle"); counts.frames+=f.frames.size; f.flush(); } };
drain();
const snapshot = () => ({...counts,mounts:f.mounts.length,pending:f.frames.size});
const delta = (a,b) => Object.fromEntries(Object.keys(a).map(k=>[k,b[k]-a[k]]));
let before=snapshot();
for(let i=0;i<100;i++) f.windowCatalogModel.update(s=>({ ...s,catalog:{...s.catalog,version:s.catalog.version+1}}));
drain(); const catalogBurst=delta(before,snapshot());
const makePublisher = new Function("createUiStateStore","appState","windowRuntimeStateMap",`let reconcilingWindowCatalog=false, focusedId=null; const windowCatalogModel=createUiStateStore({catalog:{appState:{active_tab_id:appState.active_tab_id,tabs:appState.tabs},runtimeStates:{},focusedId:null,version:0}}); ${extract("publishWindowCatalog")} ${extract("publishWindowCatalogRuntime")} return {windowCatalogModel,publishWindowCatalog,publishWindowCatalogRuntime};`);
const p=makePublisher(createUiStateStore,f.windowCatalogModel.read().catalog.appState,new Map());
let notifications=0; p.windowCatalogModel.subscribe(s=>s.catalog,()=>{notifications++;});
p.publishWindowCatalog(); notifications=0;
for(let i=0;i<100;i++) p.publishWindowCatalog();
const unchangedPublish=notifications;
p.publishWindowCatalogRuntime("one","running"); notifications=0;
for(let i=0;i<100;i++) p.publishWindowCatalogRuntime("one","running");
const unchangedStatus=notifications;
const telemetry=createUiStateStore({}, {scheduleFrame:fn=>{f.frames.add(fn);return ()=>f.frames.delete(fn);}});
const telemetrySubscription = app.match(/^      worksTelemetryModel\.subscribeFrame\(state => state, \(\) => worksSurface\.sync\([^\n]*$/m)?.[0];
if (!telemetrySubscription) throw Error("actual telemetry subscription not found");
new Function("worksTelemetryModel", "worksSurface", telemetrySubscription)(telemetry, f.surface);
drain(); before=snapshot();
for(let i=0;i<20;i++) telemetry.update(()=>({sessions:[]}));
drain(); const telemetryBurst=delta(before,snapshot());
const runtime={terminal:{cols:80,rows:24,refresh(){},focus(){}},fitAddon:{fit(){counts.fits++;},proposeDimensions(){return {cols:80,rows:24};}}};
for(let i=0;i<10;i++)runTerminalActivationSequence({runtime,windowId:"one",shouldFocus:false,shouldPersistGeometry:true,sendGeometry(){counts.geometry++;}});
const pendingAfterIdle=f.frames.size; drain();
console.log(JSON.stringify({scope:"finite module/behavior-harness probe; no browser, PTY, GUI, or historical causation",unchangedPublish100:unchangedPublish,unchangedStatus100:unchangedStatus,catalogBurst100:catalogBurst,telemetryBurst20:telemetryBurst,forcedSameGridCalls10:{fits:counts.fits,geometry:counts.geometry},pendingAfterInputStops:pendingAfterIdle}));
f.surface.dispose();p.windowCatalogModel.dispose();telemetry.dispose();
